python3 -c $'import json,sys\nW=range(32);L=["Hugo","You","Family","Doraemon"];I=lambda w,i:bool(w>>i&1);C=lambda w:bool(w&16)\nD=lambda p:any(p(v)for v in W)\nB=lambda p:all(p(v)for v in W)\nP=lambda w:I(w,0)\nR={"worlds":len(W),"agents":L,"S5_diamond_I":D(P),"S5_box_diamond_I":B(lambda w:D(P)),"S5_box_I":B(P),"S5_valid":B(lambda w:not D(P)or B(lambda v:D(P))),"cycle_and_Hugo_possible":D(lambda w:C(w)and I(w,0)),"cycle_implies_Hugo":B(lambda w:not C(w)or I(w,0)),"Hugo_implies_all":B(lambda w:not I(w,0)or all(I(w,i)for i in range(4))),"counterexample":[{"world":w,"Hugo":I(w,0),"You":I(w,1),"cycle":C(w)}for w in W if I(w,0)and not I(w,1)][:1],"scope":"finite S5 model; hypotheses only"}\nprint(json.dumps(R,ensure_ascii=False,separators=(",",":")))'
